const OpenAI = require("openai");

const client = new OpenAI({ apiKey: process.env.OPENAI_API_KEY });

const builtInPlaceholderBase64 =
  "";

const loadPlaceholderImage = async () => {
  console.info("Using built-in placeholder image (no network fetch)");
  return Buffer.from(builtInPlaceholderBase64, "base64");
};

const generateImage = async (typeImagePrompt) => {
  try {
    const prompt = `
Generate a professional 3:1 editorial news banner.

Topic:
${typeImagePrompt}

Requirements:
- Ultra realistic
- Editorial photography
- Professional news article hero image
- Modern cinematic lighting
- Rich colors
- No text
- No watermark
- No logo
- 4K quality
`;

    const model = process.env.OPENAI_IMAGE_MODEL || "gpt-image-1";
    const size = process.env.OPENAI_IMAGE_SIZE || "1024x1024";

    // console.log("OpenAI image model:", model);
    // console.log("Image size:", size);

    try {
      const result = await client.images.generate({
        model,
        prompt,
        size,
      });

      const b64 = result?.data?.[0]?.b64_json;
      if (!b64) {
        throw new Error("OpenAI returned no image data");
      }

      return Buffer.from(b64, "base64");
    } catch (err) {
      console.error("OpenAI image generation failed:", err.message || err);
      if ((process.env.USE_IMAGE_PLACEHOLDER_ON_FAILURE || "true") === "true") {
        return await loadPlaceholderImage();
      }
      return null;
    }
  } catch (err) {
    console.error("generateImage error:", err.message || err);
    if ((process.env.USE_IMAGE_PLACEHOLDER_ON_FAILURE || "true") === "true") {
      return await loadPlaceholderImage();
    }
    return null;
  }
};

module.exports = generateImage;
